"""Runs the in-tree gdbus-codegen.

Equivalent to glib's installed gdbus-codegen, but provides the codegen.config
module (normally generated by meson from config.py.in) in memory, so nothing
needs to be generated or written into the glib source tree.
"""

import os
import sys
import types

import glib_version

# Don't write __pycache__ directories into the glib source tree.
sys.dont_write_bytecode = True

_CODEGEN_PARENT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                   'src', 'gio', 'gdbus-2.0')


def main():
    version = glib_version.get_version()
    major, minor, _ = version.split('.')

    config = types.ModuleType('codegen.config')
    config.VERSION = version
    config.MAJOR_VERSION = int(major)
    config.MINOR_VERSION = int(minor)
    sys.modules['codegen.config'] = config

    sys.path.insert(0, _CODEGEN_PARENT_DIR)
    from codegen import codegen_main
    return codegen_main.codegen_main()


if __name__ == '__main__':
    sys.exit(main())
